//! PHP's own constant values for the extensions phpx implements
//! (consts_table.rs is generated by tools/consts/gen.php).

use crate::value::Value;

pub enum C {
    I(i64),
    F(f64),
    S(&'static str),
    B(bool),
    N,
}

impl C {
    pub fn value(&self) -> Value {
        match self {
            C::I(n) => Value::Int(*n),
            C::F(f) => Value::Float(*f),
            C::S(s) => Value::str(s),
            C::B(b) => Value::Bool(*b),
            C::N => Value::Null,
        }
    }
}
